6	
7	type SetValue<T> = T | ((current: T) => T);
8	
9	export type SelectionState = {
10	  selectedFolders: Set<string>;
11	  lastSelectedFolder: string;
12	  activeFolder: string;
13	  selectedNotes: Set<string>;
14	  lastSelectedNote: string;
15	  activeNote: string | null;
16	  setSelectedFolders: (value: SetValue<Set<string>>) => void;
17	  setLastSelectedFolder: (path: string) => void;
18	  setActiveFolder: (path: string) => void;
19	  setSelectedNotes: (value: SetValue<Set<string>>) => void;
20	  setLastSelectedNote: (path: string) => void;
21	  setActiveNote: (path: string | null) => void;
22	  resetSelection: () => void;
23	  selectFolderForMobile: (path: string) => void;
24	  selectNoteForMobile: (notePath: string) => void;
25	  enterMobileHome: () => void;
26	};
