28	const emptySelection = {
29	  selectedFolders: new Set<string>(),
30	  lastSelectedFolder: "",
31	  activeFolder: "",
32	  selectedNotes: new Set<string>(),
33	  lastSelectedNote: "",
34	  activeNote: null,
35	};
36	
37	const resolveValue = <T,>(value: SetValue<T>, current: T): T =>
38	  typeof value === "function" ? (value as (current: T) => T)(current) : value;
39	
40	const useSelectionStore = create<SelectionState>((set) => ({
41	  ...emptySelection,
42	  setSelectedFolders: (value) =>
43	    set((state) => ({ selectedFolders: resolveValue(value, state.selectedFolders) })),
44	  setLastSelectedFolder: (lastSelectedFolder) => set({ lastSelectedFolder }),
45	  setActiveFolder: (activeFolder) => set({ activeFolder }),
46	  setSelectedNotes: (value) =>
47	    set((state) => ({ selectedNotes: resolveValue(value, state.selectedNotes) })),
48	  setLastSelectedNote: (lastSelectedNote) => set({ lastSelectedNote }),
49	  setActiveNote: (activeNote) => set({ activeNote }),
50	  resetSelection: () =>
51	    set({
52	      ...emptySelection,
53	      selectedFolders: new Set(),
54	      selectedNotes: new Set(),
55	    }),
56	  selectFolderForMobile: (path) => {
57	    if (!path) return;
58	    set({
59	      selectedFolders: new Set([path]),
60	      lastSelectedFolder: path,
61	      activeFolder: path,
62	      selectedNotes: new Set(),
63	      lastSelectedNote: "",
64	      activeNote: null,
65	    });
66	  },
67	  selectNoteForMobile: (notePath) => {
68	    const parentPath = getNoteParentPath(notePath);
69	    set({
70	      selectedFolders: new Set(parentPath ? [parentPath] : []),
71	      lastSelectedFolder: parentPath,
72	      activeFolder: parentPath,
73	      selectedNotes: new Set([notePath]),
74	      lastSelectedNote: notePath,
75	      activeNote: notePath,
76	    });
77	  },
78	  enterMobileHome: () =>
79	    set({
80	      ...emptySelection,
81	      selectedFolders: new Set(),
82	      selectedNotes: new Set(),
83	    }),
84	}));
