1	import {
2	  useCallback,
3	  type Dispatch,
4	  type KeyboardEvent as ReactKeyboardEvent,
5	  type RefObject,
6	  type SetStateAction,
7	} from "react";
8	
9	import type { FeedTreeNode } from "@/features/notes/navigation/model/feed-tree-model";
10	import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
11	import { escapeSelectorValue, focusNoScroll, scrollIntoViewIfNeeded } from "@/shared/lib/dom";
12	import type { VisibleNavigationItem } from "@typenotes/shared/types";
13	
14	type UseFeedKeyboardNavigationArgs = {
15	  shouldNestNotesInNavigation: boolean;
16	  feedVisibleNavigationItems: VisibleNavigationItem[];
17	  feedNodeById: Map<string, FeedTreeNode>;
18	  expanded: Set<string>;
19	  setExpanded: Dispatch<SetStateAction<Set<string>>>;
20	  activeFeedGroup: string;
21	  setActiveFeedGroup: (path: string) => void;
22	  activeNote: string | null;
23	  lastSelectedFolder: string;
24	  lastSelectedNote: string;
25	  setSelectedFolders: Dispatch<SetStateAction<Set<string>>>;
26	  setLastSelectedFolder: (path: string) => void;
27	  setActiveFolder: (path: string) => void;
28	  setSelectedNotes: Dispatch<SetStateAction<Set<string>>>;
29	  setLastSelectedNote: (path: string) => void;
30	  setActiveNote: (path: string | null) => void;
31	  clearDraft: () => void;
32	  clearNote: () => void;
33	  foldersPanelRef: RefObject<HTMLDivElement | null>;
34	};
35	
36	export function useFeedKeyboardNavigation({
37	  shouldNestNotesInNavigation,
38	  feedVisibleNavigationItems,
39	  feedNodeById,
40	  expanded,
41	  setExpanded,
42	  activeFeedGroup,
43	  setActiveFeedGroup,
44	  activeNote,
45	  lastSelectedFolder,
46	  lastSelectedNote,
47	  setSelectedFolders,
48	  setLastSelectedFolder,
49	  setActiveFolder,
50	  setSelectedNotes,
51	  setLastSelectedNote,
52	  setActiveNote,
53	  clearDraft,
54	  clearNote,
55	  foldersPanelRef,
56	}: UseFeedKeyboardNavigationArgs) {
57	  return useCallback(
58	    (event: ReactKeyboardEvent<HTMLDivElement>) => {
59	      if (feedVisibleNavigationItems.length === 0) return;
60	      event.preventDefault();
61	
62	      const navIds = feedVisibleNavigationItems.map((item) => item.id);
63	      const current =
64	        lastSelectedNote && navIds.includes(lastSelectedNote)
65	          ? lastSelectedNote
66	          : lastSelectedFolder && navIds.includes(lastSelectedFolder)
67	            ? lastSelectedFolder
68	            : activeNote && navIds.includes(activeNote)
69	              ? activeNote
70	              : activeFeedGroup && navIds.includes(activeFeedGroup)
71	                ? activeFeedGroup
72	                : navIds[0];
73	      const currentIndex = Math.max(0, navIds.indexOf(current));
74	      const currentEntry = feedVisibleNavigationItems[currentIndex];
75	      if (!currentEntry) return;
76	
77	      const selectFeedGroup = (groupPath: string) => {
78	        setActiveFeedGroup(groupPath);
79	        setSelectedFolders(new Set([FEED_FOLDER_PATH]));
80	        setLastSelectedFolder(FEED_FOLDER_PATH);
81	        setActiveFolder(FEED_FOLDER_PATH);
82	        setSelectedNotes(new Set());
83	        setLastSelectedNote("");
84	        setActiveNote(null);
85	        clearDraft();
86	        clearNote();
87	        focusNoScroll(foldersPanelRef.current);
88	        requestAnimationFrame(() => {
89	          scrollIntoViewIfNeeded(
90	            foldersPanelRef.current,
91	            `[data-folder="${escapeSelectorValue(groupPath)}"]`
92	          );
93	        });
94	      };
95	
96	      const selectFeedNote = (notePath: string, parentPath: string) => {
97	        setActiveFeedGroup(parentPath);
98	        setSelectedFolders(new Set([FEED_FOLDER_PATH]));
99	        setLastSelectedFolder(FEED_FOLDER_PATH);
100	        setActiveFolder(FEED_FOLDER_PATH);
101	        setSelectedNotes(new Set([notePath]));
102	        setLastSelectedNote(notePath);
103	        setActiveNote(notePath);
104	        focusNoScroll(foldersPanelRef.current);
105	        requestAnimationFrame(() => {
106	          scrollIntoViewIfNeeded(
107	            foldersPanelRef.current,
108	            `[data-note="${escapeSelectorValue(notePath)}"]`
109	          );
110	        });
111	      };
112	
113	      if (event.key === "ArrowUp" || event.key === "ArrowDown") {
114	        const delta = event.key === "ArrowUp" ? -1 : 1;
115	        const nextIndex = Math.max(
116	          0,
117	          Math.min(feedVisibleNavigationItems.length - 1, currentIndex + delta)
118	        );
119	        const nextEntry = feedVisibleNavigationItems[nextIndex];
120	        if (!nextEntry) return;
121	        if (nextEntry.type === "folder") {
122	          selectFeedGroup(nextEntry.id);
123	          return;
124	        }
125	        selectFeedNote(nextEntry.id, nextEntry.parentId);
126	        return;
127	      }
128	
129	      if (event.key === "ArrowRight") {
130	        if (currentEntry.type !== "folder") return;
131	        const feedItem = feedNodeById.get(currentEntry.id);
132	        const hasNestedItems =
133	          Boolean(feedItem?.children.length) ||
134	          Boolean(shouldNestNotesInNavigation && feedItem?.notes.length);
135	        if (!hasNestedItems) return;
136	        if (!expanded.has(currentEntry.id)) {
137	          setExpanded((prev) => {
138	            const next = new Set(prev);
139	            next.add(currentEntry.id);
140	            return next;
141	          });
142	          return;
143	        }
144	        const firstChildEntry = feedVisibleNavigationItems[currentIndex + 1];
145	        if (!firstChildEntry || firstChildEntry.parentId !== currentEntry.id) return;
146	        if (firstChildEntry.type === "folder") {
147	          selectFeedGroup(firstChildEntry.id);
148	          return;
149	        }
150	        selectFeedNote(firstChildEntry.id, firstChildEntry.parentId);
151	        return;
152	      }
153	
154	      if (event.key === "ArrowLeft") {
155	        if (currentEntry.type === "note") {
156	          selectFeedGroup(currentEntry.parentId);
157	          return;
158	        }
159	
160	        const feedItem = feedNodeById.get(currentEntry.id);
